const shuffled = [...items];

for (let i = shuffled.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
}

return shuffled.slice(0, 2);

const shuffled = [...items];

for (let i = shuffled.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
}

return shuffled.slice(0, 3);

return $input.all().map((item) => {
  const { logo, ...binary } = item.binary ?? {};

  return {
    ...item,
    binary,
  };
});

const items = $input.all();

if (items.length !== 5) {
  throw new Error(`Cần đúng 5 ảnh, hiện có ${items.length} ảnh`);
}

const caption = items.find((item) => item.json.text)?.json.text;

if (!caption) {
  throw new Error('Không tìm thấy caption');
}

const binary = {};

items.forEach((item, index) => {
  if (!item.binary?.data) {
    throw new Error(`Ảnh thứ ${index + 1} không có binary data`);
  }

  binary[`image_${index + 1}`] = item.binary.data;
});

const marketplaceItem = items.find((item) => item.json.product_id);

const existingRequestId = items.find(
  (item) => item.json.request_id,
)?.json.request_id;

const requestId =
  existingRequestId ||
  `REQ-${new Date().toISOString().replace(/\D/g, '').slice(0, 14)}-${Math.random()
    .toString(36)
    .slice(2, 6)
    .toUpperCase()}`;

return [{
  json: {
    request_id: requestId,
    product_id: marketplaceItem?.json.product_id ?? '',
    caption,
    image_count: items.length,
  },
  binary,
}];

const draft = $input.first();

const imageKeys = Object.keys(draft.binary ?? {})
  .filter((key) => /^image_\d+$/.test(key))
  .sort((a, b) => Number(a.split('_')[1]) - Number(b.split('_')[1]));

if (imageKeys.length !== 5) {
  throw new Error(`Cần đúng 5 ảnh, hiện có ${imageKeys.length}`);
}

return imageKeys.map((key, index) => {
  const source = draft.binary[key];
  const extension = source.fileExtension || 'jpg';
  const fileName =
    `${draft.json.product_id}-preview-${String(index + 1).padStart(2, '0')}.${extension}`;

  return {
    json: {
  product_id: draft.json.product_id,
  caption: draft.json.caption,
  telegram_caption: index === 0 ? draft.json.caption : '',
  image_number: index + 1,
  drive_file_name: fileName,
},
    binary: {
      data: {
        ...source,
        fileName,
      },
    },
  };
});

const draft = $('Gom ALL thành 1 bài nháp').first();

return [{
  json: {
    ...draft.json,
    review_note: 'Đã gửi 5 ảnh và caption qua Telegram. Hãy xem Telegram trước khi chọn quyết định.',
  },
  binary: draft.binary,
}];

const form = $input.first().json;
const draft = $('Gom ALL thành 1 bài nháp').first();

const date = form['Chọn ngày đăng'];
const time = form['Chọn giờ đăng'];

if (!date || !time) {
  throw new Error('Bạn chưa chọn đủ ngày và giờ đăng');
}

return [{
  json: {
    ...draft.json,

    review_decision: form['Quyết định đăng bài'],
    scheduled_date: date,
    scheduled_time: time,
    scheduled_at: `${date}T${time}:00+07:00`,

    approval_submitted_at: form.submittedAt,
  },
  binary: draft.binary,
}];

const containers = $input.all()
  .map(item => item.json.id)
  .filter(Boolean);

if (containers.length !== 5) {
  throw new Error(`Cần đủ 5 container ảnh, hiện có ${containers.length}`);
}

const firstImage = $('Chuẩn bị ảnh cho sàn').first().json;

return [{
  json: {
    instagram_user_id: firstImage.instagram_user_id,
    caption: firstImage.caption,
    children: containers.join(','),
  },
}];

const photoIds = $input.all()
  .map(item => item.json.id)
  .filter(Boolean);

if (photoIds.length !== 5) {
  throw new Error(`Cần đủ 5 ảnh Facebook, hiện có ${photoIds.length}`);
}

const source = $('Chuẩn bị ảnh cho sàn').first().json;

return [{
  json: {
    page_id: '199011090719708',
    caption: source.caption,
    attached_media: JSON.stringify(
      photoIds.map((id) => ({ media_fbid: id }))
    ),
  },
}];

const id = $input.first().json.id;

const [pageId, postId] = id.split('_');

if (!pageId || !postId) {
  throw new Error(`Post ID không đúng định dạng: ${id}`);
}

return [{
  json: {
    facebook_post_id: id,
    facebook_url: `https://www.facebook.com/${pageId}/posts/${postId}`,
  },
}];

const post = $input.first().json;
const uploaded = $('Upload 5 ảnh preview lên Drive').all();

const files = uploaded
  .map((item, index) => {
    const id = item.json.id;
    const name = item.json.name || `Ảnh ${index + 1}`;
    const match = name.match(/preview-(\d+)/i);

    return {
      id,
      order: match ? Number(match[1]) : index + 1,
    };
  })
  .filter((file) => file.id)
  .sort((a, b) => a.order - b.order);

if (files.length !== 5) {
  throw new Error(`Cần 5 ảnh Drive, hiện có ${files.length}`);
}

return files.map((file, index) => ({
  json: {
    instagram_user_id: '27663207950044918',
    image_number: index + 1,
    image_url: `https://drive.google.com/uc?export=download&id=${file.id}`,
    caption: post.caption,
  },
}));
